export class GraphDynamics {

    public width: number;
    public height: number;
    public nodes: Node[] = [];
    public edges: Edge[] = [];
    public dt: number = 0.0;

    public mouse: NVector3 = new NVector3(0, 0);

    public damping = 0.96;
    public gravity = -0.032;
    public timeStep = 0.16; // 0.316; // 0.18; // 0.26;
    public groundZ = -9.26;

    public capture: Node | undefined = undefined;

    constructor(x: number, y: number, width: number, height: number) {

        this.init(x, y, width, height);
    }
    public init(x: number, y: number, width: number, height: number) {
        this.initGridR(x, y, width, height);
        this.nodes[0].fixed = true;
        this.nodes[9].fixed = true;
        this.nodes[this.nodes.length - 1].fixed = true;
        this.nodes[this.nodes.length - 1 - 9].fixed = true;
    }
    public updateOptionA(v: number) {
        this.damping = v * 0.1;
        // console.log(this.damping, 'damping');
    }
    public updateOptionB(v: number) {
        this.timeStep = v * 0.05;
        // console.log(this.timeStep, 'timeStep');
    }
    public updateOptionC(v: number) {
        // this.gravity = v * 0.1;
        // console.log(this.gravity, 'gravity');
    }
    public initGridR(xS: number, yS: number, width: number, height: number, xNum: number = 10, yNum: number = 10) {
        const xOff = 0;
        const yOff = 0;
        const xInterval = (width / xNum) + 1;
        const yInterval = (height / yNum) + 1;
        const nbase = this.nodes.length;
        for (let i = 0; i < yNum; ++i) {
            for (let j = 0; j < xNum; ++j) {
                let x = xS + xOff + xInterval * j;
                let y = yS + yOff + yInterval * i;
                let z = 0;
                this.addNode(new NVector3(x, y, z), NVector3.zero(), 1.0);
                // this.nodes.push(new Node(new NVector3(x, y), new NVector3(0, 0), 1));
            }
        }
        for (let j = 0; j < yNum; ++j) {
            for (let i = 0; i < xNum; ++i) {
                let k = j * xNum + i;

                if (i !== 0) { this.addEdge(this.nodes[nbase + k - 1], this.nodes[nbase + k]); }
                if (j !== 0) { this.addEdge(this.nodes[nbase + k - xNum], this.nodes[nbase + k]); }

                // if (i !== 0 && j !== 0) {this.AddEdge(this.nodes[nbase + k - xNum - 1], this.nodes[nbase + k]); }

                // if (i !== 0 && j !== yNum - 1) {this.AddEdge(this.nodes[nbase + k + xNum - 1], this.nodes[nbase + k]); }
            }
        }
    }
    public clear() {
        this.nodes = [];
        this.edges = [];
    }
    public addNode(_p0: NVector3, _u0: NVector3, _mass: number): Node {
        const n = new Node(_p0, _u0, _mass);
        this.nodes.push(n);
        return n;
    }
    public addEdge(n0: Node, n1: Node): Edge {
        const e = new Edge(n0, n1);
        this.edges.push(e);
        return e;
    }
    public mouseMove(x: number, y: number) {
        this.mouse.x = x;
        this.mouse.y = y;
        // console.log('move', x, y);
    }
    public mouseDClick(x: number, y: number) {
        this.mouse.x = x;
        this.mouse.y = y;
        const n = this.findNode(this.mouse);
        if (n) {
            n.fixed = !n.fixed;
        }
        // console.log('click', x, y);
    }
    public mouseDown(x: number, y: number) {
        this.mouse.x = x;
        this.mouse.y = y;
        this.capture = this.findNode(this.mouse);
        if (this.capture) {
            this.capture.fixed = true;
            this.capture.isCapture = true;
        }
        // console.log('down', x, y, this.capture);
    }
    public mouseLeftClick(x: number, y: number) {
        // console.log('click', x, y, this.capture);
    }
    public mouseUp(x: number, y: number) {
        this.mouse.x = x;
        this.mouse.y = y;
        if (this.capture) {
            this.capture.isCapture = false;
            this.capture = undefined;
        }
        // console.log('up', x, y);
    }
    public mouseDrag(x: number, y: number) {
        this.mouse.x = x;
        this.mouse.y = y;
        if (this.capture) {
            this.capture.v.x = x;
            this.capture.v.y = y;
        }
        // console.log('drag', x, y);
    }
    public render(ctx?: CanvasRenderingContext2D) {

        this.dt += 0.1;
        this.move(this.mouse.x, this.mouse.y, this.mouse.z, this.damping, 0, this.timeStep, this.groundZ, 1);

        for (let e of this.edges) { e.render(ctx); }
        for (let n of this.nodes) { n.render(ctx, this.mouse); }
    }
    public findNode(mv: NVector3) {
        for (let n of this.nodes) {
            if (n.v.distance(mv) < n.m + 3) {
                return n;
            }
        }
        return undefined;
    }
    public move(x: number, y: number, z: number, damping: number, g: number = 0, dt: number = 0.01, groundZ: number = -10, step: number = 1) {
        const atr = new NVector3(x, y, z);
        for (let i = 0; i < step; ++i) {
            for (const n of this.nodes) {
                
                // const dv: NVector3 = atr - n.p;
                //  L = dv.Length;
                // dv.Unitize();
                // n.f = dv * Math.Exp(-0.1 * L * L) * 0.1 + Vector3d.ZAxis * g;

                const dv = NVector3.sub(atr, n.v);
                const L = dv.length();
                dv.normalize();
                n.f = NVector3.add(NVector3.scale(dv, Math.exp(-0.1 * L * L) * 0.1), (NVector3.scale(NVector3.YAxis(), g)));
            }
            for (const e of this.edges) { e.applySpringForce(); }
            for (const n of this.nodes) { n.move(dt, damping, groundZ); }
        }
    }
}
export class Edge {
    n0: Node;
    n1: Node;
    public targetLength: number = 0.0;
    public springConstant: number = 0.8; // 1; // 0.8;
    constructor(n0: Node, n1: Node) {
        this.n0 = n0;
        this.n1 = n1;
        this.targetLength = this.n0.v.distance(this.n1.v) * 1;
    }
    render(ctx: CanvasRenderingContext2D) {
        ctx.strokeStyle = '#ff0000';

        if (NVector3.distance(this.n0.v, this.n1.v) < this.targetLength * 2) {
            ctx.strokeStyle = '#0000ff';
            // this.n0.isShort = true;
            // this.n1.isShort = true;
        }

        ctx.beginPath();
        ctx.moveTo(this.n0.v.x, this.n0.v.y);
        ctx.lineTo(this.n1.v.x, this.n1.v.y);
        ctx.closePath();
        ctx.stroke();
    }
    public applySpringForce() {
        // Vector3d dp = n1.p - n0.p;
        // double dist = dp.Length;
        // dp.Unitize();

        // n0.f += dp * (dist - TargetLength) * SpringConstant;
        // n1.f -= dp * (dist - TargetLength) * SpringConstant;

        // const dp: NVector3 = NVector3.Sub(this.n1.p, this.n0.p);
        // const dist:number = dp.Length();
        // dp.Unitize();

        let dp = NVector3.sub(this.n1.v, this.n0.v);
        let dist = dp.length();
        dp.normalize();

        const length = NVector3.scale(
            dp, (dist - this.targetLength) * this.springConstant
        );
        this.n0.f = NVector3.add(this.n0.f, length);
        this.n1.f = NVector3.sub(this.n1.f, length);
    }
}
export class Node {
    public nNodes: Node[] = [];
    public v: NVector3 = NVector3.zero();
    public f: NVector3 = NVector3.zero();
    public u: NVector3 = NVector3.zero();
    public m: number = 0.0;

    public fixed: boolean = false;
    public isCapture: boolean = false;

    constructor(_p0: NVector3, _u0: NVector3, _mass: number) {
        this.v = new NVector3(_p0.x, _p0.y, _p0.z);
        this.u = new NVector3(_u0.x, _u0.y, _u0.z);
        this.m = _mass;
    }
    public move(dt: number, damping: number, groundZ: number = 0.0) {
        if (this.fixed || this.isCapture) { return; }

        // u *= damping;
        // u += f * (dt / m);
        // p += u * dt;

        // this.u = NVector3.Scale(this.u , damping );
        // this.u = NVector3.Add( this.u,  NVector3.Scale(this.f, dt / this.m));
        // this.p  = NVector3.Add(this.p, NVector3.Scale(this.u, dt));

        this.u.scale(damping);
        this.u.add(NVector3.scale(this.f, dt / this.m));

        const v = NVector3.scale(this.u, dt);
        // this.v.Add( );
        this.v.x += v.x;
        this.v.y += v.y;

        // if (this.p.y < groundZ) {
        //     this.p.y = groundZ;
        //     if (this.u.y < 0.0) {this.u.y = -this.u.y; }
        // }
    }
    public render(ctx: CanvasRenderingContext2D, m: NVector3) {
        ctx.beginPath();

        if (m.distance(this.v) < this.m + 3) {
            ctx.fillStyle = '#000000';
            ctx.arc(this.v.x, this.v.y, this.m + 6, 0.0, Math.PI * 2);
        } else {
            ctx.fillStyle = '#f90000';
            ctx.arc(this.v.x, this.v.y, this.m + 3, 0.0, Math.PI * 2);
        }

        if (this.fixed) {
            ctx.fillStyle = '#000000';
            ctx.arc(this.v.x, this.v.y, this.m + 7.5, 0.0, Math.PI * 2);
        }

        ctx.closePath();
        ctx.fill();
    }
}


export class NVector3 { 
    public static zero(): NVector3 {
        return new NVector3(0, 0, 0);
    }
    public static YAxis(): NVector3 {
        return new NVector3(0, 1, 0);
    }
    public static distance(v0: NVector3, v1: NVector3): number {
        return Math.sqrt((v0.x - v1.x) * (v0.x - v1.x) + (v0.y - v1.y) * (v0.y - v1.y) + (v0.z - v1.z) * (v0.z - v1.z));
    }
    public static add(v0: NVector3, v1: NVector3): NVector3 {
        return new NVector3(v0.x + v1.x, v0.y + v1.y, v0.z + v1.z);
      }
    public static sub(v0: NVector3, v1: NVector3): NVector3 {
        return new NVector3(v0.x - v1.x, v0.y - v1.y, v0.z - v1.z);
    }
    public static scale(v: NVector3, s: number): NVector3 {
        return new NVector3(v.x * s, v.y * s, v.z * s);
    }
    public x: number = 0;
    public y: number = 0;
    public z: number = 0;
    constructor(x: number, y: number, z: number = 0) {
        this.x = x;
        this.y = y;
        this.z = z;
      }
    public distance(v: NVector3): number {
        return NVector3.distance(new NVector3(this.x, this.y, this.z), v);
    }
    public add(v: NVector3): NVector3 {
        this.x += v.x;
        this.y += v.y;
        this.z += v.z;
        return this;
    }
    public scale(v: number): NVector3 {
        this.x *= v;
        this.y *= v;
        this.z *= v;
        return this;
    }
    public length(): number {
        const len = Math.sqrt(this.x * this.x + this.y * this.y + this.z * this.z);
        if (len < 0.00001) {
          return 0.00001;
        }
        return len;
    }
    public normalize(): NVector3 {
        let len: number = Math.sqrt(this.x * this.x + this.y * this.y + this.z * this.z);
        if (len < 0.0001) {
          return this;
        }
        this.x = this.x / len;
        this.y = this.y / len;
        this.z = this.z / len;
        return this;
      }
}